import{_ as l,a0 as n,w as r,s as p,ao as d,I as o,x as t,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"IceWM：一個非常酷的桌面 | LCTT x X-CMD","titleTemplate":false,"description":"IceWM：一個非常酷的桌面 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"IceWM：一個非常酷的桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"IceWM：一個非常酷的桌面 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191007 IceWM - A really cool desktop","title":"IceWM：一個非常酷的桌面","tag":"201910","desc":""},"relativePath":"201910/20191007 IceWM - A really cool desktop.md","filePath":"[post].md"}'),c={name:"201910/20191007 IceWM - A really cool desktop.md"};function h(m,e,g,u,f,k){const a=n("Link");return r(),p("div",null,[e[15]||(e[15]=d('<h1 id="icewm-一個非常酷的桌面" tabindex="-1">IceWM：一個非常酷的桌面 <a class="header-anchor" href="#icewm-一個非常酷的桌面" aria-label="Permalink to “IceWM：一個非常酷的桌面”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/09/icewm-1-816x346.png" alt=""></p><p>IceWM 是一款非常輕量的桌面。它已經出現 20 多年了，它今天的目標仍然與當時相同：速度、簡單性以及不妨礙用户。</p><p>我曾經將 IceWM 添加到 Scientific Linux 中作為輕量級桌面。當時它只是 0.5 兆的 rpm 包。運行時，它僅使用 5 兆的內存。這些年來，IceWM 有所增長。rpm 包現在為 1 兆。運行時，IceWM 現在使用 10 兆的內存。儘管在過去十年中它的大小增加了一倍，但它仍然非常小。</p><p>這麼小的包，你能得到什麼？確切地説，就是一個窗口管理器。沒有其他東西。你有一個帶有菜單或圖標的工具欄來啓動程序。速度很快。最後，還有主題和選項。除了工具欄中的一些小東西，就只有這些了。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/09/icewm.2-1024x768.png" alt=""></p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>因為 IceWM 很小，你只需安裝主軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install icewm</span></span></code></pre></div><p>如果要節省磁盤空間，許多依賴項都是可選的。沒有它們，IceWM 也可以正常工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install icewm --setopt install_weak_deps=false</span></span></code></pre></div><h3 id="選項" tabindex="-1">選項 <a class="header-anchor" href="#選項" aria-label="Permalink to “選項”">​</a></h3><p>IceWM 默認已經設置完畢，以使普通的 Windows 用户也能感到舒適。這是一件好事，因為選項是通過配置文件手動完成的。</p><p>我希望你不會因此而止步，因為它並沒有聽起來那麼糟糕。它只有 8 個配置文件，大多數人只使用其中幾個。主要的三個配置文件是 <code>keys</code>（鍵綁定），<code>preferences</code>（總體首選項）和 <code>toolbar</code>（工具欄上顯示的內容）。默認配置文件位於 <code>/usr/share/icewm/</code>。</p><p>要進行更改，請將默認配置複製到 IceWM 家目錄（<code>~/.icewm</code>），編輯文件，然後重新啓動 IceWM。第一次做可能會有點害怕，因為在 “Logout” 菜單項下可以找到 “Restart Icewm”。但是，當你重啓 IceWM 時，你只會看到閃爍一下，更改就生效了。任何打開的程序均不受影響，並保持原樣。</p><h3 id="主題" tabindex="-1">主題 <a class="header-anchor" href="#主題" aria-label="Permalink to “主題”">​</a></h3><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/09/icewm.3-1024x771.png" alt="IceWM in the NanoBlue theme"></p><p>如果安裝 icewm-themes 包，那麼會得到很多主題。與常規選項不同，你無需重啓 IceWM 即可更改為新主題。通常我不會談論主題，但是由於其他功能很少，因此我想提下。</p><h3 id="工具欄" tabindex="-1">工具欄 <a class="header-anchor" href="#工具欄" aria-label="Permalink to “工具欄”">​</a></h3><p>工具欄是為 IceWM 添加了更多的功能的地方。你可以看到它可以切換不同的工作區。工作區有時稱為虛擬桌面。單擊工作區圖標以移動到它。右鍵單擊一個窗口的任務欄項目，可以在工作區之間移動它。如果你喜歡工作區，它擁有你想要的所有功能。如果你不喜歡工作區，那麼可以選擇關閉它。</p><p>工具欄還有網絡/內存/CPU 監控圖。將鼠標懸停在圖標上可獲得詳細信息。單擊圖標可以打開一個擁有完整監控功能的窗口。這些小圖形曾經出現在每個窗口管理器上。但是，隨着桌面環境的成熟，它們都將這些圖形去除了。我很高興 IceWM 留下了這個不錯的功能。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你想要輕量但功能強大的桌面，IceWM 適合你。它已經設置好了，因此新的 Linux 用户也可以立即使用它。它是靈活的，因此 Unix 用户可以根據自己的喜好進行調整。最重要的是，IceWM 可以讓你的程序不受阻礙地運行。</p><hr>',24)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),s(a,{href:"https://fedoramagazine.org/icewm-a-really-cool-desktop/"},{default:i(()=>[...e[0]||(e[0]=[t("https://fedoramagazine.org/icewm-a-really-cool-desktop/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),s(a,{href:"https://fedoramagazine.org/author/tdawson/"},{default:i(()=>[...e[2]||(e[2]=[t("tdawson",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),s(a,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),s(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const W=l(c,[["render",h]]);export{M as __pageData,W as default};
